import React from "react";

export default function Feedback() {
  return (
    <div className="text-center mt-10">
      <h1 className="text-3xl font-bold text-blue-600">Interview Feedback</h1>
      <p className="mt-4 text-lg text-gray-600">
        View your interview performance and AI-generated feedback here.
      </p>
    </div>
  );
}
